css:
html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
}

.ls58-widget {
  --ls58-metal: #D7D8DB;
  --ls58-outline: #4E4E4E;
  --ls58-fiber: #0A638F;
  --ls58-steam: #930606;
  --ls58-condensate: #4E4E4E;
  --ls58-control: #01524F;
  --ls58-valve: #0E0E55;
  --ls58-text: #000000;

  display: grid;
  place-items: center;

  width: 100%;
  height: 100%;

  overflow: hidden;
  background: transparent;

  font-family: "Segoe UI", Arial, sans-serif;
  pointer-events: none;
}

.ls58-svg {
  display: block;
  width: 100%;
  height: 100%;

  overflow: hidden;
  background: transparent;

  shape-rendering: geometricPrecision;
}

/* Gradientes */

.ls58-metal-stop {
  stop-color: var(--ls58-metal);
}

/* Elementos metálicos */

.ls58-metal {
  fill: url("#ls58-metal-gradient");
  stroke: var(--ls58-outline);
  stroke-width: 1.4px;
  stroke-linejoin: round;
}

.ls58-metal-side {
  fill: url("#ls58-side-gradient");
  stroke: var(--ls58-outline);
  stroke-width: 1.4px;
  stroke-linejoin: round;
}

.ls58-metal-top {
  fill: url("#ls58-top-gradient");
  stroke: var(--ls58-outline);
  stroke-width: 1.4px;
  stroke-linejoin: round;
}

.ls58-soft-shadow {
  filter: url("#ls58-equipment-shadow");
}

.ls58-detail {
  fill: none;
  stroke: var(--ls58-outline);
  stroke-width: 0.9px;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.ls58-mechanical-line {
  fill: none;
  stroke: var(--ls58-outline);
  stroke-width: 1.2px;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.ls58-highlight {
  fill: none;
  stroke: #FFFFFF;
  stroke-width: 0.8px;
  stroke-linecap: round;
  opacity: 0.55;
}

.ls58-frame {
  fill: none;
  stroke: #7D838B;
  stroke-width: 0.9px;
}

/* Poleas: sin barras ni anillos interiores */

.ls58-roller-body {
  fill: url("#ls58-roller-metal");
  stroke: var(--ls58-outline);
  stroke-width: 2.2px;

  filter: url("#ls58-roller-shadow");
}

/* Cuerda */

.ls58-fiber {
  fill: none;
  stroke: var(--ls58-fiber);
  stroke-width: 1.8px;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: none;
}

/* Líneas de proceso */

.ls58-steam,
.ls58-condensate,
.ls58-control {
  fill: none;
  stroke-width: 1.6px;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: none;
}

.ls58-steam {
  stroke: var(--ls58-steam);
}

.ls58-condensate {
  stroke: var(--ls58-condensate);
}

.ls58-control {
  stroke: var(--ls58-control);
}

.ls58-valve-connection {
  stroke-linecap: butt;
}

.ls58-steam-arrow {
  fill: var(--ls58-steam);
  stroke: var(--ls58-steam);
  stroke-width: 1.2px;
  stroke-linejoin: round;
}

.ls58-condensate-arrow {
  fill: var(--ls58-condensate);
  stroke: var(--ls58-condensate);
  stroke-width: 1.2px;
  stroke-linejoin: round;
}

/* Válvulas horizontales */

.ls58-valve-body {
  fill: none;
  stroke: var(--ls58-valve);
  stroke-width: 1.4px;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.ls58-valve-stem {
  fill: none;
  stroke: var(--ls58-valve);
  stroke-width: 0.7px;
  stroke-linecap: butt;
}

.ls58-valve-actuator {
  fill: var(--ls58-valve);
  stroke: var(--ls58-valve);
  stroke-width: 1px;
}

/* Dispositivos mecánicos */

.ls58-device-body {
  fill: url("#ls58-metal-gradient");
  stroke: var(--ls58-valve);
  stroke-width: 1.2px;
  stroke-linejoin: round;
}

.ls58-device-detail {
  fill: none;
  stroke: var(--ls58-valve);
  stroke-width: 0.9px;
  stroke-linecap: round;
}

.ls58-joint {
  fill: var(--ls58-metal);
  stroke: var(--ls58-outline);
  stroke-width: 0.9px;
}

/* Depósito de desperdicio */

.ls58-waste-front {
  fill: url("#ls58-waste-gradient");
  stroke: #4F1111;
  stroke-width: 1.4px;
  stroke-linejoin: round;
}

.ls58-waste-opening {
  fill: #390505;
  stroke: #4F1111;
  stroke-width: 1.1px;
}

.ls58-waste-flap {
  fill: url("#ls58-flap-gradient");
  stroke: #542121;
  stroke-width: 1px;
  stroke-linejoin: round;
}

.ls58-waste-label {
  fill: #FFFFFF;
  font-family: "Segoe UI", Arial, sans-serif;
  font-size: 10px;
  font-weight: 600;
  text-anchor: middle;
}

/* Texto inferior */

.ls58-footer {
  fill: var(--ls58-text);
  font-size: 16px;
  font-style: italic;
  font-weight: 500;
  text-anchor: end;
}

